class Counter {
  #n;
  constructor(start = 0) {
    this.#n = start;
  }
  inc() {
    this.#n += 1;
    return this.#n;
  }
  value() {
    return this.#n;
  }
}
class StepCounter extends Counter {
  constructor(start, step) {
    super(start);
    this.step = step;
  }
  inc() {
    let n = this.value();
    for (let i = 0; i < this.step; i++) n = super.inc();
    return n;
  }
}
